\section{Hitting times}

\begin{theorem}\label{thm:hitting_is_stopping_time}
  \uses{def:IsStoppingTime, def:hittingAfter, def:IsStronglyProgressive, def:hasUsualConditions}
  \leanok
  \lean{MeasureTheory.isStoppingTime_hittingAfter'}
If $X : T \to \Omega \to E$ is a progressively measurable process with respect to a filtration satisfying the usual conditions and $B$ is a Borel-measurable subset of $E$, then the hitting time of $X$ in $B$ is a stopping time.
\end{theorem}

\begin{proof}\leanok
  \uses{thm:debut_of_progr_meas_is_stop_time}
Since $B$ is a Borel subset of $\mathcal{S}$ and $X$ is progressively measurable, then $\mathbf{1}_B(X_t)$ is also progressively measurable.
The hitting time is then the debut of the set $E = \{(s,\omega) : \mathbf{1}_B(X_s(\omega)) = 1\}$, and therefore is a stopping time by Theorem~\ref{thm:debut_of_progr_meas_is_stop_time}.
\end{proof}


\begin{definition}\label{def:leastGE}
  \mathlibok
  \lean{MeasureTheory.leastGE}
Let $T$ be a conditionally complete linear order with a bottom element and let $R$ be a preorder.
For a process $X : T \to Ω \to R$ and $a \in R$, define the random time
\begin{align*}
  \tau_{X \ge a} = \inf\{t \in T \mid X_t \ge a\} \: ,
\end{align*}
in which the infimum is infinite if the set is empty.
\end{definition}


\begin{lemma}\label{lem:isStoppingTime_leastGE}
  \uses{def:IsStoppingTime, def:leastGE}
  \leanok
  \lean{MeasureTheory.isStoppingTime_leastGE}
Let $T$ be a conditionally complete linear order with a bottom element, which is a Polish space for its order topology, on which we put the Borel $\sigma$-algebra.
Let $R$ be a preorder with a metrizable topology for which sets of the form $\{x \in R \mid x \ge a\}$ are closed, with its Borel $\sigma$-algebra.
If $X : T \to Ω \to R$ is a progressively measurable process with respect to a filtration satisfying the usual conditions, then for any $a \in R$, the random time $\tau_{X \ge a}$ is a stopping time.
\end{lemma}

\begin{proof}\leanok
  \uses{thm:hitting_is_stopping_time}
This is a direct application of Theorem~\ref{thm:hitting_is_stopping_time} with the set $B = [a, +\infty)$.
\end{proof}


\begin{corollary}\label{cor:isStoppingTime_leastGE_of_rightContinuous}
  \uses{def:IsStoppingTime, def:leastGE, def:rightContinuous, def:adapted, def:RightContinuous}
If $X : ι \to Ω \to ℝ$ is a right-continuous and adapted process with respect to a filtration satisfying the usual conditions, then for any $a \in \mathbb{R}$, the random time $\tau_{X \ge a}$ is a stopping time.
\end{corollary}

\begin{proof}
  \uses{lem:isStoppingTime_leastGE, lem:Adapted.isStronglyProgressive_of_rightContinuous}
This follows from Lemma~\ref{lem:isStoppingTime_leastGE} since $X$ is progressively measurable by Lemma~\ref{lem:Adapted.isStronglyProgressive_of_rightContinuous}.
\end{proof}


\begin{definition}\label{def:leastGT}
  \leanok
  \lean{MeasureTheory.leastGT}
Let $T$ be a conditionally complete linear order with a bottom element and let $R$ be a preorder.
For a process $X : T \to Ω \to R$ and $a \in R$, define the random time
\begin{align*}
  \tau_{X > a} = \inf\{t \in T \mid X_t > a\} \: ,
\end{align*}
in which the infimum is infinite if the set is empty.
\end{definition}


\begin{lemma}\label{lem:isStoppingTime_leastGT}
  \uses{def:IsStoppingTime, def:leastGT}
  \leanok
  \lean{MeasureTheory.isStoppingTime_leastGT}
Let $T$ be a conditionally complete linear order with a bottom element, which is a Polish space for its order topology, on which we put the Borel $\sigma$-algebra.
Let $R$ be a preorder with a metrizable topology for which sets of the form $\{x \in R \mid x \ge a\}$ are closed, with its Borel $\sigma$-algebra.
If $X : T \to Ω \to R$ is a progressively measurable process with respect to a filtration satisfying the usual conditions, then for any $a \in R$, the random time $\tau_{X > a}$ is a stopping time.
\end{lemma}

\begin{proof}\leanok
  \uses{thm:hitting_is_stopping_time}
This is a direct application of Theorem~\ref{thm:hitting_is_stopping_time} with the set $B = (a, +\infty)$.
\end{proof}


\begin{lemma}\label{lem:leastGT_lt_iff}
  \uses{def:leastGT}
  \leanok
  \lean{MeasureTheory.leastGT_lt_iff}
For $t \in T$, $\tau_{X > a} < t$ if and only if there exists $s < t$ such that $X_s > a$.
\end{lemma}

\begin{proof}\leanok
  \uses{def:leastGT}

\end{proof}

\begin{lemma}\label{lem:isLocalizingSequence_leastGE}
  \uses{def:leastGE, def:localizingSequence, def:IsCadlag, def:rightContinuous}
  \leanok
  \lean{ProbabilityTheory.isLocalizingSequence_leastGE}
Assume $T$ has a bottom element and that its closed intervals are compact, and that the filtration is right-continuous.
If $X$ is a real-valued càdlàg and adapted process, then the sequence $\tau_n := \inf \{t | X_t \ge n\}$ is a localizing sequence.
\end{lemma}

\begin{proof}
  \uses{lem:isBounded_image_of_isCadlag_of_isCompact, cor:isStoppingTime_leastGE_of_rightContinuous}
  \leanok
By Corollary~\ref{cor:isStoppingTime_leastGE_of_rightContinuous}, each $\tau_n$ is a stopping time. Moreover, for all $n \in \mathbb{N}$, $X_t \ge n+1 \implies X_t \ge n$, thus $\tau_n \le \tau_{n+1}$. Finally, for every $\omega \in \Omega$ and $t_0 \in T$ there exists $N \in \mathbb{N}$ such that for all $s \le t_0$, $X_s \le N$ thanks to Lemma~\ref{lem:isBounded_image_of_isCadlag_of_isCompact}. Thus for all $n \ge N$, $\tau_n(\omega) \ge t_0$, proving that $\tau_n$ tends to infinity as n goes to infinity.
\end{proof}


\begin{lemma}\label{lem:sup_stoppedProcess_le}
  \uses{def:stoppedProcess}
  \leanok
  \lean{ProbabilityTheory.sup_stoppedProcess_leastGE_le}
For $Y$ a stochastic process, let $Y^*_t = \sup_{s \le t} \Vert Y_s \Vert$.
Let $X$ be a stochastic process and let $\tau = \inf \{t \mid \Vert X_t \Vert \ge n\}$ for some $n \in \mathbb{R}$.
Then
\begin{align*}
  (X^{\tau})^*_t
  \le n + \mathbb{1}_{\tau \le t} \Vert X_{\tau} \Vert
  \: .
\end{align*}
\end{lemma}

\begin{proof}\leanok
If $\tau > t$, then for all $s \le t$, $\|X_s\| \le n$, and thus $(X^\tau)^*_t = \sup_{s \le t} \|X_{\tau \land s}\| \le n = n + \mathbb{1}_{\tau \le t} \|X_{\tau}\|$. Otherwise $(X^\tau)^*_t = \sup_{s \le \tau} \|X_s\|$. For $s < \tau$, $\|X_s\| \le n$, and $\|X_\tau\| \le \|X_\tau\|$ so $\sup_{s \le \tau} \|X_s\| \le n \lor \|X_\tau\| \le n + \|X_\tau\| = n + \mathbb{I}_{\tau \le t} \|X_\tau\|$.
\end{proof}


\begin{lemma}\label{lem:ClassDL.hasLocallyIntegrableSup}
  \uses{def:classD, def:locallyIntegrableSup, def:IsCadlag, def:rightContinuous}
  \leanok
  \lean{ProbabilityTheory.ClassDL.hasLocallyIntegrableSup}
Assume $T$ has a bottom element and that its closed intervals are compact, and that the filtration is right-continuous.
If $X$ is a càdlàg process of class DL, then it has locally integrable supremum.
\end{lemma}

\begin{proof}\leanok
  \uses{lem:isLocalizingSequence_leastGE, lem:sup_stoppedProcess_le,lem:IsStronglyProgressive.hasStronglyMeasurableSup}
Set $\tau_n := \inf \{t | X_t \ge n\}$. This is a localizing sequence by Lemma~\ref{lem:isLocalizingSequence_leastGE}. For every $t \in T$, we have by Lemma~\ref{lem:sup_stoppedProcess_le} that $(X^{\tau_n})^*_t \le n + \mathbb{I}_{\tau_n \le t} \|X_{\tau_n}\| = n + \mathbb{I}_{\tau_n \le t} \|X_{\tau_n \land t}\|$. Because X is of class DL, $X_{\tau_n \land t}$ is integrable, so $(X^{\tau_n})^*_t$ is integrable too, so $(X^{\tau_n} \mathbb{I}_{\tau_n > 0})^*_t$ is integrable. Thus $X$ has locally integrable supremum.
\end{proof}


\begin{lemma}\label{lem:hasLocallyIntegrableSup_of_locally_classDL}
  \uses{def:classDL, def:locallyIntegrableSup, def:locally, def:IsCadlag, def:rightContinuous}
  \leanok
  \lean{ProbabilityTheory.hasLocallyIntegrableSup_of_locally_classDL}
Assume $T$ has a bottom element and that its closed intervals are compact.

